BEGIN;

CREATE FUNCTION refs_read_ai_vendor_invoice_amount_spike_findings(p_tenant uuid,p_entity uuid,p_limit integer DEFAULT 20)
RETURNS TABLE(ai_vendor_invoice_amount_anomaly_finding_id uuid,rule_id text,risk_level text,confidence numeric,reason text,suggested_action text,source_document_id uuid,source_document_line_id uuid,source_payload_hash text,source_line_hash text,created_at timestamptz,can_create_draft boolean,can_review boolean,can_approve boolean,can_post boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN PERFORM refs_assert_ai_analysis_scope(p_tenant,p_entity);IF p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN RAISE EXCEPTION 'AI anomaly limit must be between 1 and 100' USING ERRCODE='22023';END IF;RETURN QUERY SELECT f.ai_vendor_invoice_amount_anomaly_finding_id,f.finding->>'rule_id',f.finding->>'risk_level',(f.finding->>'confidence')::numeric,f.finding->>'reason',f.finding->>'suggested_action',f.source_document_id,f.source_document_line_id,f.source_payload_hash,f.source_line_hash,f.created_at,false,false,false,false FROM ai_vendor_invoice_amount_anomaly_finding f WHERE f.tenant_id=p_tenant AND f.entity_id=p_entity AND f.status='OPEN' ORDER BY f.created_at DESC LIMIT p_limit;END $$;

