RETURNS TABLE(ai_vendor_invoice_frequency_anomaly_finding_id uuid,rule_id text,risk_level text,confidence numeric,reason text,suggested_action text,source_document_id uuid,source_document_line_id uuid,source_payload_hash text,source_line_hash text,created_at timestamptz,can_create_draft boolean,can_review boolean,can_approve boolean,can_post boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN PERFORM refs_assert_ai_analysis_scope(p_tenant,p_entity);IF p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN RAISE EXCEPTION 'AI anomaly limit must be between 1 and 100' USING ERRCODE='22023';END IF;RETURN QUERY SELECT f.ai_vendor_invoice_frequency_anomaly_finding_id,f.finding->>'rule_id',f.finding->>'risk_level',(f.finding->>'confidence')::numeric,f.finding->>'reason',f.finding->>'suggested_action',s.source_document_id,s.source_document_line_id,s.source_payload_hash,s.source_line_hash,f.created_at,false,false,false,false FROM ai_vendor_invoice_frequency_anomaly_finding f JOIN ai_vendor_invoice_frequency_anomaly_source s ON s.tenant_id=f.tenant_id AND s.entity_id=f.entity_id AND s.ai_vendor_invoice_frequency_anomaly_finding_id=f.ai_vendor_invoice_frequency_anomaly_finding_id AND s.source_ordinal=0 WHERE f.tenant_id=p_tenant AND f.entity_id=p_entity AND f.status='OPEN' ORDER BY f.created_at DESC LIMIT p_limit;END $$;

