RETURNS TABLE(ai_vendor_invoice_amount_drop_finding_id uuid,rule_id text,risk_level text,confidence numeric,reason text,suggested_action text,source_document_id uuid,source_document_line_id uuid,source_payload_hash text,source_line_hash text,created_at timestamptz,can_create_draft boolean,can_review boolean,can_approve boolean,can_post boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN PERFORM refs_assert_ai_analysis_scope(p_tenant,p_entity);IF p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN RAISE EXCEPTION 'AI anomaly limit must be between 1 and 100' USING ERRCODE='22023';END IF;RETURN QUERY SELECT f.ai_vendor_invoice_amount_drop_finding_id,f.finding->>'rule_id',f.finding->>'risk_level',(f.finding->>'confidence')::numeric,f.finding->>'reason',f.finding->>'suggested_action',f.source_document_id,f.source_document_line_id,f.source_payload_hash,f.source_line_hash,f.created_at,false,false,false,false FROM ai_vendor_invoice_amount_drop_finding f WHERE f.tenant_id=p_tenant AND f.entity_id=p_entity AND f.status='OPEN' ORDER BY f.created_at DESC LIMIT p_limit;END $$;

CREATE FUNCTION refs_read_ai_vendor_invoice_near_duplicate_findings(p_tenant uuid,p_entity uuid,p_limit integer DEFAULT 20)
RETURNS TABLE(ai_vendor_invoice_near_duplicate_finding_id uuid,rule_id text,risk_level text,confidence numeric,reason text,suggested_action text,source_document_id uuid,source_document_line_id uuid,source_payload_hash text,source_line_hash text,created_at timestamptz,can_create_draft boolean,can_review boolean,can_approve boolean,can_post boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN PERFORM refs_assert_ai_analysis_scope(p_tenant,p_entity);IF p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN RAISE EXCEPTION 'AI anomaly limit must be between 1 and 100' USING ERRCODE='22023';END IF;RETURN QUERY SELECT f.ai_vendor_invoice_near_duplicate_finding_id,f.finding->>'rule_id',f.finding->>'risk_level',(f.finding->>'confidence')::numeric,f.finding->>'reason',f.finding->>'suggested_action',s.source_document_id,s.source_document_line_id,s.source_payload_hash,s.source_line_hash,f.created_at,false,false,false,false FROM ai_vendor_invoice_near_duplicate_finding f JOIN ai_vendor_invoice_near_duplicate_source s ON s.tenant_id=f.tenant_id AND s.entity_id=f.entity_id AND s.ai_vendor_invoice_near_duplicate_finding_id=f.ai_vendor_invoice_near_duplicate_finding_id AND s.source_ordinal=1 WHERE f.tenant_id=p_tenant AND f.entity_id=p_entity AND f.status='OPEN' ORDER BY f.created_at DESC LIMIT p_limit;END $$;

CREATE FUNCTION refs_read_ai_manual_journal_risk_findings(p_tenant uuid,p_entity uuid,p_limit integer DEFAULT 20)
RETURNS TABLE(ai_manual_journal_risk_finding_id uuid,rule_id text,risk_level text,confidence numeric,reason text,suggested_action text,journal_entry_id uuid,finding_hash text,created_at timestamptz,can_create_draft boolean,can_review boolean,can_approve boolean,can_post boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN PERFORM refs_assert_ai_analysis_scope(p_tenant,p_entity);IF p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN RAISE EXCEPTION 'AI anomaly limit must be between 1 and 100' USING ERRCODE='22023';END IF;RETURN QUERY SELECT f.ai_manual_journal_risk_finding_id,coalesce(f.finding->'rule_ids'->>0,'AI_MANUAL_JOURNAL_RISK'),f.finding->>'risk_level',(f.finding->>'confidence')::numeric,f.finding->>'reason',f.finding->>'suggested_action',f.journal_entry_id,f.finding_hash,f.created_at,false,false,false,false FROM ai_manual_journal_risk_finding f WHERE f.tenant_id=p_tenant AND f.entity_id=p_entity AND f.status='OPEN' ORDER BY f.created_at DESC LIMIT p_limit;END $$;

CREATE OR REPLACE FUNCTION refs_read_ai_accounting_analysis_summary(p_tenant uuid,p_entity uuid) RETURNS TABLE(category text,total_findings bigint,high_findings bigint,medium_findings bigint,low_findings bigint,latest_materialized_at timestamptz,can_create_draft boolean,can_review boolean,can_approve boolean,can_post boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
  PERFORM refs_assert_ai_analysis_scope(p_tenant,p_entity);
  RETURN QUERY WITH retained AS (
    SELECT 'WBS_EXCEPTION'::text category,risk_level,created_at FROM ai_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'PREPAID_COVERAGE',risk_level,created_at FROM ai_prepaid_coverage_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'DUPLICATE_PAYABLE',risk_level,created_at FROM ai_duplicate_payable_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'BANK_DUPLICATE_PAYMENT',finding->>'risk_level',created_at FROM ai_bank_duplicate_payment_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'VENDOR_INVOICE_AMOUNT_SPIKE',finding->>'risk_level',created_at FROM ai_vendor_invoice_amount_anomaly_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'VENDOR_INVOICE_FREQUENCY_SPIKE',finding->>'risk_level',created_at FROM ai_vendor_invoice_frequency_anomaly_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'VENDOR_INVOICE_AMOUNT_DROP',finding->>'risk_level',created_at FROM ai_vendor_invoice_amount_drop_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'VENDOR_INVOICE_NEAR_DUPLICATE',finding->>'risk_level',created_at FROM ai_vendor_invoice_near_duplicate_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'MANUAL_JOURNAL_RISK',finding->>'risk_level',created_at FROM ai_manual_journal_risk_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'UNMATCHED_BANK_PAYMENT',risk_level,created_at FROM ai_unmatched_bank_payment_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'COST_DIMENSION',risk_level,created_at FROM ai_cost_dimension_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
    UNION ALL SELECT 'LOAN_REFERENCE',risk_level,created_at FROM ai_loan_reference_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='OPEN'
  ) SELECT retained.category,count(*)::bigint,count(*) FILTER(WHERE retained.risk_level='HIGH')::bigint,count(*) FILTER(WHERE retained.risk_level='MEDIUM')::bigint,count(*) FILTER(WHERE retained.risk_level='LOW')::bigint,max(retained.created_at),false,false,false,false FROM retained GROUP BY retained.category ORDER BY retained.category;
END $$;

DO $$ DECLARE definition text;categories text:='''BANK_DUPLICATE_PAYMENT'', ''VENDOR_INVOICE_AMOUNT_SPIKE'', ''VENDOR_INVOICE_FREQUENCY_SPIKE'', ''VENDOR_INVOICE_AMOUNT_DROP'', ''VENDOR_INVOICE_NEAR_DUPLICATE'', ''MANUAL_JOURNAL_RISK'', ''UNMATCHED_BANK_PAYMENT''';BEGIN
  SELECT pg_get_functiondef('refs_assert_ai_accounting_analysis_summary(jsonb)'::regprocedure) INTO definition;definition:=replace(definition,'jsonb_array_length(p_summary)>7','jsonb_array_length(p_summary)>12');definition:=replace(definition,'''BANK_DUPLICATE_PAYMENT'',''UNMATCHED_BANK_PAYMENT''',categories);IF position('MANUAL_JOURNAL_RISK' IN definition)=0 OR position('jsonb_array_length(p_summary)>12' IN definition)=0 THEN RAISE EXCEPTION 'Full AI summary integration failed';END IF;EXECUTE definition;
  SELECT pg_get_functiondef('refs_assert_ai_accounting_analysis_evidence(jsonb)'::regprocedure) INTO definition;definition:=replace(definition,'''BANK_DUPLICATE_PAYMENT'',''UNMATCHED_BANK_PAYMENT''',categories);IF position('MANUAL_JOURNAL_RISK' IN definition)=0 THEN RAISE EXCEPTION 'Full AI evidence integration failed';END IF;EXECUTE definition;
  SELECT pg_get_functiondef('refs_complete_ai_accounting_analysis_explanation(uuid,uuid,text,text,jsonb)'::regprocedure) INTO definition;definition:=replace(definition,'''BANK_DUPLICATE_PAYMENT'',''UNMATCHED_BANK_PAYMENT''',categories);IF position('MANUAL_JOURNAL_RISK' IN definition)=0 THEN RAISE EXCEPTION 'Full AI explanation integration failed';END IF;EXECUTE definition;
END $$;

REVOKE ALL ON FUNCTION refs_read_ai_vendor_invoice_amount_spike_findings(uuid,uuid,integer),refs_read_ai_vendor_invoice_frequency_spike_findings(uuid,uuid,integer),refs_read_ai_vendor_invoice_amount_drop_findings(uuid,uuid,integer),refs_read_ai_vendor_invoice_near_duplicate_findings(uuid,uuid,integer),refs_read_ai_manual_journal_risk_findings(uuid,uuid,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION refs_read_ai_vendor_invoice_amount_spike_findings(uuid,uuid,integer),refs_read_ai_vendor_invoice_frequency_spike_findings(uuid,uuid,integer),refs_read_ai_vendor_invoice_amount_drop_findings(uuid,uuid,integer),refs_read_ai_vendor_invoice_near_duplicate_findings(uuid,uuid,integer),refs_read_ai_manual_journal_risk_findings(uuid,uuid,integer) TO refs_app;
COMMIT;
